#include <bits/stdc++.h>
#include<vector>
#include<algorithm>
using namespace std;
using ll=long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        
        vector<ll> coef(3*n);
        for(auto& c:coef){
            cin>>c;
        }
        sort(coef.rbegin(),coef.rend());
        vector<ll>prefix(3*n+1,0);
        for(int i = 0; i<3*n;i++){
            prefix[i+1]=prefix[i]+coef[i];
        }
        ll best = 0;
        for(int s = 0;s<=n;s++){
            int mF=n-s;
            
            auto score = [&](int fours)->ll{int foursEnd=s+2*fours;
            int threeEnd=3*n-2*s-fours;
            return 2*prefix[s]+prefix[foursEnd]+3* prefix[threeEnd];
            };
            if(mF==0){
                best= max(best,score(0));
                continue;
            }
            auto gainfrom1more=[&](int fours)->ll{ int foursEnd = s + 2 * fours;
            int threeEnd = 3*n-2*s-fours;
            
            return coef[foursEnd]+coef[foursEnd+1]-3*coef[threeEnd-1];
            };
            
            int lo=0,hi=mF;
            while(lo<hi){
                int mid = (lo+hi)/2;
                if(gainfrom1more(mid)>=0){
                    lo =mid+1;
                }
                else{
                    hi = mid;
                }
            }
            
            best =max(best,score(lo));
            if(lo<0) best = max (best,score(lo-1));

            
        }
        cout<< best<<endl;
    }
    
}
